package com.cat.client

import android.content.Context
import org.json.JSONObject
import java.math.BigInteger
import java.net.HttpURLConnection
import java.net.URL
import java.security.SecureRandom
import java.text.SimpleDateFormat
import java.util.Base64
import java.util.Date
import java.util.Locale
import java.util.TimeZone

/**
 * Real Cloudflare WARP registration for `awg://auto@…` / `wireguard://auto@…` configs.
 *
 * Earlier builds put a fixed placeholder private key (`YAutoGenerated…=`) into those configs.
 * That key was never registered with Cloudflare, so the WireGuard handshake could never succeed
 * — every built-in "AWG / WARP" entry silently failed. This object generates a real X25519 key
 * pair (pure Kotlin, works on every Android version), registers it with the public WARP API
 * (the same flow wgcf / Aether use), caches the account, and swaps the placeholder for it right
 * before the core starts.
 */
object WarpRegistration {
    const val PLACEHOLDER_PRIVATE_KEY = "YAutoGeneratedClientPrivateKeyForWarpTunnel="
    const val WARP_PEER_PUBLIC_KEY = "bmXOC+F1FxEMF9dyiK2H5/1SUtzH0JuVo51h2wPfgyo="
    private const val PREFS = "cat_client_warp_account"
    private const val KEY_JSON = "account"
    private val API_URLS = listOf(
        "https://api.cloudflareclient.com/v0a2158/reg",
        "https://api.cloudflareclient.com/v0a1922/reg",
    )

    data class Account(
        val privateKey: String,
        val publicKey: String,
        val peerPublicKey: String,
        val ipv4: String,
        val ipv6: String?,
        val reserved: List<Int>?,
        val accountId: String,
    ) {
        fun toJson(): JSONObject = JSONObject()
            .put("privateKey", privateKey)
            .put("publicKey", publicKey)
            .put("peerPublicKey", peerPublicKey)
            .put("ipv4", ipv4)
            .put("ipv6", ipv6.orEmpty())
            .put("reserved", reserved?.joinToString(",").orEmpty())
            .put("id", accountId)

        companion object {
            fun fromJson(o: JSONObject): Account? {
                val priv = o.optString("privateKey").takeIf { it.length >= 43 } ?: return null
                return Account(
                    privateKey = priv,
                    publicKey = o.optString("publicKey"),
                    peerPublicKey = o.optString("peerPublicKey").ifBlank { WARP_PEER_PUBLIC_KEY },
                    ipv4 = o.optString("ipv4").ifBlank { "172.16.0.2" },
                    ipv6 = o.optString("ipv6").takeIf(String::isNotBlank),
                    reserved = o.optString("reserved").split(',').mapNotNull { it.trim().toIntOrNull() }
                        .takeIf { it.size == 3 },
                    accountId = o.optString("id"),
                )
            }
        }
    }

    fun cached(context: Context): Account? {
        val raw = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getString(KEY_JSON, null) ?: return null
        return runCatching { Account.fromJson(JSONObject(raw)) }.getOrNull()
    }

    fun forget(context: Context) {
        context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().remove(KEY_JSON).apply()
    }

    /** Returns the cached account or registers a new one. Blocking network call. */
    fun ensureAccount(context: Context): Account? = ensureAccountDetailed(context).account

    /** Where the key in use came from, for the plain-language status the user asked for. */
    enum class Source { Cached, CatWarpCore, DirectApi, CatWarpCoreNew, None }

    data class Outcome(val account: Account?, val source: Source, val log: List<String>)

    /**
     * beta209: the old flow only tried one plain HTTPS request to `api.cloudflareclient.com`, which Iranian networks
     * usually block — so every built-in WARP / AmneziaWG row kept the placeholder key and could never connect.
     * Order now:
     *  1. the key this app already registered;
     *  2. the WireGuard key the Cat Warp core already holds (`aether-store.toml`, only while Cloudflare still has it
     *     as a WireGuard key — a MASQUE enrolment destroys it);
     *  3. a plain request to the WARP API;
     *  4. a registration through the Cat Warp core itself (fragmented, browser-fingerprinted TLS, several API hosts),
     *     then step 2 again.
     */
    fun ensureAccountDetailed(context: Context, allowCoreRegistration: Boolean = true): Outcome {
        val log = mutableListOf<String>()
        cached(context)?.let { return Outcome(it, Source.Cached, listOf("cached key")) }
        val identity = java.io.File(context.filesDir, "aether.toml")
        AetherIdentityStore.wireGuardAccount(identity)?.let {
            return Outcome(it, Source.CatWarpCore, listOf("Cat Warp core WireGuard key ${it.accountId.take(8)}…"))
        }
        val direct = runCatching { register() }.getOrNull()
        if (direct != null) {
            context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit()
                .putString(KEY_JSON, direct.toJson().toString()).apply()
            return Outcome(direct, Source.DirectApi, listOf("registered via WARP API"))
        }
        log += "WARP API unreachable on this line"
        if (allowCoreRegistration) {
            val provisioned = runCatching {
                AetherOperations.provision(AetherMode.WireGuard, identity, ipScan = "both", exitLocation = "iran")
            }.getOrElse { Result.failure(it) }
            provisioned.exceptionOrNull()?.let { log += "Cat Warp core: ${it.message.orEmpty().take(160)}" }
            AetherIdentityStore.wireGuardAccount(identity)?.let {
                return Outcome(it, Source.CatWarpCoreNew, log + "Cat Warp core registered WireGuard key ${it.accountId.take(8)}…")
            }
        }
        return Outcome(null, Source.None, log)
    }

    fun register(random: SecureRandom = SecureRandom()): Account? {
        val privateBytes = ByteArray(32).also(random::nextBytes)
        clamp(privateBytes)
        val publicBytes = publicKeyOf(privateBytes)
        val privateB64 = Base64.getEncoder().encodeToString(privateBytes)
        val publicB64 = Base64.getEncoder().encodeToString(publicBytes)
        val tos = SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", Locale.US)
            .apply { timeZone = TimeZone.getTimeZone("UTC") }
            .format(Date())
        val body = JSONObject()
            .put("key", publicB64)
            .put("install_id", "")
            .put("fcm_token", "")
            .put("tos", tos)
            .put("model", "PC")
            .put("serial_number", "")
            .put("locale", "en_US")
            .toString()
        for (endpoint in API_URLS) {
            val response = runCatching { post(endpoint, body) }.getOrNull() ?: continue
            parseRegistration(response, privateB64, publicB64)?.let { return it }
        }
        return null
    }

    internal fun parseRegistration(json: String, privateB64: String, publicB64: String): Account? = runCatching {
        val root = JSONObject(json).let { it.optJSONObject("result") ?: it }
        val config = root.optJSONObject("config") ?: return null
        val peer = config.optJSONArray("peers")?.optJSONObject(0)
        val addresses = config.optJSONObject("interface")?.optJSONObject("addresses")
        val reserved = config.optString("client_id").takeIf(String::isNotBlank)?.let { clientId ->
            runCatching { Base64.getDecoder().decode(clientId) }.getOrNull()
                ?.takeIf { it.size >= 3 }
                ?.take(3)
                ?.map { it.toInt() and 0xFF }
        }
        Account(
            privateKey = privateB64,
            publicKey = publicB64,
            peerPublicKey = peer?.optString("public_key")?.takeIf(String::isNotBlank) ?: WARP_PEER_PUBLIC_KEY,
            ipv4 = addresses?.optString("v4")?.takeIf(String::isNotBlank) ?: "172.16.0.2",
            ipv6 = addresses?.optString("v6")?.takeIf(String::isNotBlank),
            reserved = reserved,
            accountId = root.optString("id"),
        )
    }.getOrNull()

    /**
     * Replaces the placeholder key in every WireGuard block of [yaml] with the registered account
     * and injects its IPv6 address / reserved bytes when the block does not define them.
     */
    fun patchYaml(yaml: String, account: Account): String {
        if (!yaml.contains(PLACEHOLDER_PRIVATE_KEY)) return yaml
        fun indentOf(line: String) = line.takeWhile { it == ' ' }.length
        val lines = yaml.lines()
        val out = ArrayList<String>(lines.size + 8)
        var idx = 0
        while (idx < lines.size) {
            val line = lines[idx]
            if (!line.trimStart().startsWith("- ")) {
                out += line.replace(PLACEHOLDER_PRIVATE_KEY, account.privateKey)
                idx++
                continue
            }
            val itemIndent = indentOf(line)
            var end = idx + 1
            while (end < lines.size && lines[end].isNotBlank() && indentOf(lines[end]) > itemIndent) end++
            val block = lines.subList(idx, end)
            val keyLine = block.firstOrNull { it.contains(PLACEHOLDER_PRIVATE_KEY) }
            if (keyLine == null) {
                out += block
            } else {
                val keys = block.map { it.trim().removePrefix("- ").substringBefore(':').trim() }.toSet()
                val childIndent = " ".repeat(
                    if (keyLine.trimStart().startsWith("- ")) itemIndent + 2 else indentOf(keyLine),
                )
                block.forEach { out += it.replace(PLACEHOLDER_PRIVATE_KEY, account.privateKey) }
                if (account.ipv6 != null && "ipv6" !in keys) out += "${childIndent}ipv6: ${account.ipv6}"
                if (account.reserved != null && "reserved" !in keys) {
                    out += "${childIndent}reserved: [${account.reserved.joinToString(", ")}]"
                }
            }
            idx = end
        }
        return out.joinToString("\n")
    }

    // ---- beta210: every WARP WireGuard config gets our own working key automatically ---------------------------

    private const val KEY_ADOPT = "adopt_warp_configs"
    private const val KEY_PREWARM_AT = "prewarm_at"
    private const val PREWARM_EVERY_MS = 3L * 60 * 60 * 1000

    /** ON by default: WireGuard configs that point at Cloudflare WARP run with this app's own registered key. */
    fun adoptsWarpConfigs(context: Context): Boolean =
        context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).getBoolean(KEY_ADOPT, true)

    fun setAdoptsWarpConfigs(context: Context, on: Boolean) {
        context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit().putBoolean(KEY_ADOPT, on).apply()
    }

    /** True when [yaml] holds a WARP WireGuard peer (Cloudflare's public key) or an `auto` placeholder. */
    fun containsWarpPeer(yaml: String): Boolean =
        yaml.contains(PLACEHOLDER_PRIVATE_KEY) || yaml.contains(WARP_PEER_PUBLIC_KEY)

    private val autoLock = Any()
    @Volatile private var lastAutoFailureAt = 0L
    private const val AUTO_RETRY_AFTER_MS = 10L * 60 * 1000

    /**
     * Automatic (no-button) key fetch used on connect, by delay tests and by the background prewarm: one at a time,
     * and after a failure it waits 10 minutes instead of stalling every connect / test on a blocked line.
     */
    fun ensureAccountAutomatic(context: Context, nowMs: Long = System.currentTimeMillis()): Outcome {
        cached(context)?.let { return Outcome(it, Source.Cached, listOf("cached key")) }
        synchronized(autoLock) {
            cached(context)?.let { return Outcome(it, Source.Cached, listOf("cached key")) }
            val since = nowMs - lastAutoFailureAt
            if (lastAutoFailureAt > 0 && since in 0 until AUTO_RETRY_AFTER_MS) {
                AetherIdentityStore.wireGuardAccount(java.io.File(context.filesDir, "aether.toml"))?.let {
                    return Outcome(it, Source.CatWarpCore, listOf("Cat Warp core WireGuard key ${it.accountId.take(8)}…"))
                }
                return Outcome(null, Source.None, listOf("last automatic attempt failed ${since / 1000}s ago; retrying after 10 min"))
            }
            val outcome = ensureAccountDetailed(context)
            lastAutoFailureAt = if (outcome.account == null) nowMs else 0L
            return outcome
        }
    }

    /** True when a usable key is already on the phone (no network needed). */
    fun hasUsableKey(context: Context): Boolean =
        cached(context) != null ||
            AetherIdentityStore.wireGuardAccount(java.io.File(context.filesDir, "aether.toml")) != null

    /**
     * Gets the key in the background before the user ever taps connect, so WARP rows just work. Rate-limited
     * (one attempt per 3 h) and only when the user actually has WARP rows. Blocking — call off the main thread.
     */
    fun prewarmIfUseful(context: Context, hasWarpRows: Boolean, nowMs: Long = System.currentTimeMillis()): Outcome? {
        if (!hasWarpRows || hasUsableKey(context)) return null
        val prefs = context.getSharedPreferences(PREFS, Context.MODE_PRIVATE)
        val last = prefs.getLong(KEY_PREWARM_AT, 0L)
        if (last in 1..nowMs && nowMs - last < PREWARM_EVERY_MS) return null
        prefs.edit().putLong(KEY_PREWARM_AT, nowMs).apply()
        return ensureAccountAutomatic(context, nowMs)
    }

    private fun indentOf(line: String) = line.takeWhile { it == ' ' }.length
    private fun unquote(v: String) = v.trim().removeSurrounding("'").removeSurrounding("\"")
    private fun q(v: String) = "'" + v.replace("'", "''") + "'"

    /**
     * Rewrites every WARP WireGuard proxy in a Cat core YAML so it uses [account]: private key, IPv4, IPv6 and the
     * reserved bytes (the old ones belong to someone else's account and would break the handshake). Server, port,
     * MTU and AmneziaWG options stay as they were. Handles block-style and one-line `- {…}` items; multi-peer
     * (`peers:`) items are left alone.
     */
    fun adoptWarpPeers(yaml: String, account: Account): String {
        if (!containsWarpPeer(yaml)) return yaml
        val lines = yaml.split('\n')
        val out = ArrayList<String>(lines.size + 16)
        var inProxies = false
        var itemIndent = -1
        var i = 0
        while (i < lines.size) {
            val line = lines[i]
            val ind = indentOf(line)
            if (line.isNotBlank() && ind == 0 && !line.startsWith("-")) {
                inProxies = line.substringBefore(':').trim() == "proxies"
                itemIndent = -1
                out += line
                i++
                continue
            }
            if (inProxies && line.trimStart().startsWith("- ") && (itemIndent == -1 || ind == itemIndent)) {
                itemIndent = ind
                var end = i + 1
                while (end < lines.size && lines[end].isNotBlank() && indentOf(lines[end]) > ind) end++
                out += rewriteItem(lines.subList(i, end), ind, account)
                i = end
                continue
            }
            out += line
            i++
        }
        return out.joinToString("\n")
    }

    private fun rewriteItem(block: List<String>, ind: Int, account: Account): List<String> {
        val first = block.first().trimStart().removePrefix("- ").trimStart()
        if (block.size == 1 && first.startsWith("{")) return listOf(rewriteFlowItem(block.first(), account))
        val keyed = block.mapIndexed { idx, l ->
            val body = if (idx == 0) first else l.trim()
            body.substringBefore(':').trim().removeSurrounding("'").removeSurrounding("\"") to body.substringAfter(':', "")
        }
        val topLevel = block.indices.filter { it == 0 || indentOf(block[it]) == ind + 2 }.toSet()
        val values = keyed.filterIndexed { idx, _ -> idx in topLevel }.associate { it.first to it.second }
        val isWarp = unquote(values["type"].orEmpty()).equals("wireguard", ignoreCase = true) &&
            "peers" !in values &&
            (unquote(values["public-key"].orEmpty()) == WARP_PEER_PUBLIC_KEY ||
                unquote(values["private-key"].orEmpty()) == PLACEHOLDER_PRIVATE_KEY)
        if (!isWarp) return block
        val child = " ".repeat(ind + 2)
        val out = ArrayList<String>(block.size + 3)
        var skipDeeperThan = -1
        val seen = HashSet<String>()
        block.forEachIndexed { idx, l ->
            val lineIndent = if (idx == 0) ind + 2 else indentOf(l)
            if (skipDeeperThan >= 0) {
                if (idx > 0 && lineIndent > skipDeeperThan) return@forEachIndexed
                skipDeeperThan = -1
            }
            val key = if (idx in topLevel) keyed[idx].first else ""
            val prefix = if (idx == 0) l.substring(0, l.indexOf('-')) + "- " else " ".repeat(lineIndent)
            when (key) {
                "private-key" -> { out += "$prefix$key: ${q(account.privateKey)}"; seen += key }
                "ip" -> { out += "$prefix$key: ${q(account.ipv4)}"; seen += key }
                "ipv6", "reserved" -> {
                    seen += key
                    if (keyed[idx].second.isBlank()) skipDeeperThan = lineIndent
                    val replacement = if (key == "ipv6") account.ipv6?.let { q(it) } else account.reserved?.joinToString(", ", "[", "]")
                    if (replacement != null) {
                        out += "$prefix$key: $replacement"
                    } else if (idx == 0) {
                        out += l
                    }
                }
                else -> out += l
            }
        }
        if ("ip" !in seen) out += "${child}ip: ${q(account.ipv4)}"
        if ("ipv6" !in seen) account.ipv6?.let { out += "${child}ipv6: ${q(it)}" }
        if ("reserved" !in seen) account.reserved?.let { out += "${child}reserved: ${it.joinToString(", ", "[", "]")}" }
        return out
    }

    private fun flowKey(key: String) = Regex("""(?<=[\{,\s])(['"]?)""" + Regex.escape(key) + """\1\s*:\s*""")

    private fun rewriteFlowItem(line: String, account: Account): String {
        val open = line.indexOf('{')
        val close = line.lastIndexOf('}')
        if (open < 0 || close <= open) return line
        var body = line.substring(open, close)
        fun valueOf(key: String): String? = flowKey(key).find(body)?.let { m ->
            body.substring(m.range.last + 1).let { rest ->
                when {
                    rest.startsWith("'") -> rest.drop(1).substringBefore('\'')
                    rest.startsWith("\"") -> rest.drop(1).substringBefore('"')
                    else -> rest.substringBefore(',').trim()
                }
            }
        }
        val isWarp = valueOf("type").equals("wireguard", ignoreCase = true) && flowKey("peers").find(body) == null &&
            (valueOf("public-key") == WARP_PEER_PUBLIC_KEY || valueOf("private-key") == PLACEHOLDER_PRIVATE_KEY)
        if (!isWarp) return line
        fun put(key: String, value: String?) {
            val m = flowKey(key).find(body)
            if (m == null) {
                if (value != null) body = "$body, $key: $value"
                return
            }
            val start = m.range.first
            val rest = body.substring(m.range.last + 1)
            val valueLen = when {
                rest.startsWith("'") -> rest.indexOf('\'', 1) + 1
                rest.startsWith("\"") -> rest.indexOf('"', 1) + 1
                rest.startsWith("[") -> rest.indexOf(']') + 1
                else -> rest.indexOfFirst { it == ',' }.let { if (it < 0) rest.length else it }
            }.coerceAtLeast(0)
            val tail = body.substring(m.range.last + 1 + valueLen)
            val head = body.substring(0, start).trimEnd().removeSuffix(",")
            body = if (value == null) head + tail else body.substring(0, start) + "$key: $value" + tail
        }
        put("private-key", q(account.privateKey))
        put("ip", q(account.ipv4))
        put("ipv6", account.ipv6?.let { q(it) })
        put("reserved", account.reserved?.joinToString(", ", "[", "]"))
        return line.substring(0, open) + body + line.substring(close)
    }

    private fun post(url: String, body: String): String? {
        val connection = (URL(url).openConnection() as HttpURLConnection).apply {
            requestMethod = "POST"
            connectTimeout = 10_000
            readTimeout = 15_000
            doOutput = true
            setRequestProperty("Content-Type", "application/json; charset=UTF-8")
            setRequestProperty("User-Agent", "okhttp/3.12.1")
            setRequestProperty("CF-Client-Version", "a-6.30-3596")
        }
        return try {
            connection.outputStream.use { it.write(body.toByteArray(Charsets.UTF_8)) }
            if (connection.responseCode !in 200..299) return null
            connection.inputStream.bufferedReader().use { it.readText() }
        } finally {
            connection.disconnect()
        }
    }

    // ---- X25519 (RFC 7748) -------------------------------------------------------------------

    private val P: BigInteger = BigInteger.ONE.shiftLeft(255).subtract(BigInteger.valueOf(19))
    private val A24: BigInteger = BigInteger.valueOf(121665)
    private val BASE_POINT = ByteArray(32).also { it[0] = 9 }

    fun clamp(scalar: ByteArray) {
        scalar[0] = (scalar[0].toInt() and 248).toByte()
        scalar[31] = ((scalar[31].toInt() and 127) or 64).toByte()
    }

    fun publicKeyOf(privateKey: ByteArray): ByteArray = x25519(privateKey, BASE_POINT)

    fun x25519(scalar: ByteArray, uCoordinate: ByteArray): ByteArray {
        require(scalar.size == 32 && uCoordinate.size == 32)
        val k = scalar.copyOf().also(::clamp)
        val kInt = BigInteger(1, k.reversedArray())
        val u = uCoordinate.copyOf().also { it[31] = (it[31].toInt() and 127).toByte() }
        val x1 = BigInteger(1, u.reversedArray()).mod(P)
        var x2 = BigInteger.ONE
        var z2 = BigInteger.ZERO
        var x3 = x1
        var z3 = BigInteger.ONE
        var swap = 0
        for (t in 254 downTo 0) {
            val kt = if (kInt.testBit(t)) 1 else 0
            swap = swap xor kt
            if (swap == 1) {
                x2 = x3.also { x3 = x2 }
                z2 = z3.also { z3 = z2 }
            }
            swap = kt
            val a = x2.add(z2).mod(P)
            val aa = a.multiply(a).mod(P)
            val b = x2.subtract(z2).mod(P)
            val bb = b.multiply(b).mod(P)
            val e = aa.subtract(bb).mod(P)
            val c = x3.add(z3).mod(P)
            val d = x3.subtract(z3).mod(P)
            val da = d.multiply(a).mod(P)
            val cb = c.multiply(b).mod(P)
            val sum = da.add(cb).mod(P)
            val diff = da.subtract(cb).mod(P)
            x3 = sum.multiply(sum).mod(P)
            z3 = x1.multiply(diff.multiply(diff).mod(P)).mod(P)
            x2 = aa.multiply(bb).mod(P)
            z2 = e.multiply(aa.add(A24.multiply(e)).mod(P)).mod(P)
        }
        if (swap == 1) {
            x2 = x3.also { x3 = x2 }
            z2 = z3.also { z3 = z2 }
        }
        val result = x2.multiply(z2.modPow(P.subtract(BigInteger.valueOf(2)), P)).mod(P)
        val be = result.toByteArray()
        val out = ByteArray(32)
        // big-endian (possibly with sign byte) → 32-byte little-endian
        for (idx in 0 until 32) {
            val src = be.size - 1 - idx
            out[idx] = if (src >= 0) be[src] else 0
        }
        return out
    }
}
